import json
from fractions import Fraction

def mul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(2)) for j in range(2)] for i in range(2)]

def add(A, B):
    return [[A[i][j] + B[i][j] for j in range(2)] for i in range(2)]

def neg(A):
    return [[-A[i][j] for j in range(2)] for i in range(2)]

def norm(A):
    # induced infinity-norm (max absolute row sum), submultiplicative
    return max(sum(abs(A[i][j]) for j in range(2)) for i in range(2))

def mpow(A, n):
    R = [[Fraction(1), Fraction(0)], [Fraction(0), Fraction(1)]]
    for _ in range(n):
        R = mul(R, A)
    return R

def nth_root_exact(v, n):
    # returns exact value of v^(1/n) when v is 0 or 1; None otherwise
    if v == 0:
        return Fraction(0)
    if v == 1:
        return Fraction(1)
    return None

